pub fn doc_by_id(id: &str) -> Option<&'static EmbeddedDoc> {
    DOCS.iter().find(|doc| doc.id == id)
}

pub fn doc_title(id: &str) -> Option<&'static str> {
    doc_by_id(id).map(|doc| doc.title)
}
